-- Edit the source app's migration history only until the cutover; after that, edit here.

SET search_path TO lms, extensions;

-- Users can read their own row
CREATE POLICY "users: read own" ON lms.users
  FOR SELECT USING (auth.uid() = id);

-- Admins can read all users
CREATE POLICY "users: admin read all" ON lms.users
  FOR SELECT USING (
    EXISTS (SELECT 1 FROM lms.users WHERE id = auth.uid() AND role = 'admin')
  );

-- Teachers can read their assigned learners
CREATE POLICY "users: teacher read assigned" ON lms.users
  FOR SELECT USING (
    EXISTS (
      SELECT 1 FROM lms.teacher_assignments
      WHERE teacher_id = auth.uid() AND learner_id = users.id AND is_active = TRUE
    )
  );

-- All authenticated users can read published modules
CREATE POLICY "modules: read published" ON lms.modules
  FOR SELECT USING (auth.uid() IS NOT NULL AND is_published = TRUE AND deleted_at IS NULL);

-- Admins can do everything
CREATE POLICY "modules: admin all" ON lms.modules
  USING (EXISTS (SELECT 1 FROM lms.users WHERE id = auth.uid() AND role = 'admin'));

-- Learners see their own progress
CREATE POLICY "progress: learner own" ON lms.learner_progress
  FOR SELECT USING (learner_id = auth.uid());

-- Teachers see progress of assigned learners
CREATE POLICY "progress: teacher assigned" ON lms.learner_progress
  FOR SELECT USING (
    EXISTS (
      SELECT 1 FROM lms.teacher_assignments
      WHERE teacher_id = auth.uid() AND learner_id = learner_progress.learner_id AND is_active = TRUE
    )
  );

-- Admins see all
CREATE POLICY "progress: admin all" ON lms.learner_progress
  USING (EXISTS (SELECT 1 FROM lms.users WHERE id = auth.uid() AND role = 'admin'));

-- Activity logs policies (add as needed, basic examples):
CREATE POLICY "activity_logs: user read own" ON lms.activity_logs
  FOR SELECT USING (user_id = auth.uid());

CREATE POLICY "activity_logs: admin all" ON lms.activity_logs
  USING (EXISTS (SELECT 1 FROM lms.users WHERE id = auth.uid() AND role = 'admin'));

-- Storage policies for 'study-notes' bucket (assumes bucket exists)
-- Since Supabase storage uses auth.uid(), we can write these now.
-- Note: 'storage' schema might require extensions or different handling in local dev, 
-- but we include it here as per SPEC.
-- To properly add storage policies, the bucket must exist, so we might need a separate script
-- to insert the bucket. We'll skip storage policies in this script and assume they are added via UI/API,
-- or we can insert into storage.buckets first.

INSERT INTO storage.buckets (id, name, public) VALUES ('study-notes', 'study-notes', false)
ON CONFLICT (id) DO NOTHING;

CREATE POLICY "storage: authenticated read"
  ON storage.objects FOR SELECT
  USING (bucket_id = 'study-notes' AND auth.uid() IS NOT NULL);

CREATE POLICY "storage: admin write"
  ON storage.objects FOR INSERT
  WITH CHECK (
    bucket_id = 'study-notes' AND
    EXISTS (SELECT 1 FROM lms.users WHERE id = auth.uid() AND role = 'admin')
  );
